import{bQ as a,aL as t,u as s,G as n}from"./chunks/framework.C1gZXFVa.js";const u=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/quick-start.md","filePath":"en/guide/quick-start.md"}'),i={name:"en/guide/quick-start.md"};function l(o,e,r,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><blockquote><p><strong>The route in one line</strong>: check your server&#39;s OS, architecture and Python version → pick the matching bundle from the table → copy it over and run <code>install.sh</code> → <code>&quot;ping&quot;: &quot;pong&quot;</code> means you are done.</p></blockquote><h2 id="before-you-start-check-your-server-s-info" tabindex="-1">Before you start: check your server&#39;s info <a class="header-anchor" href="#before-you-start-check-your-server-s-info" aria-label="Permalink to &quot;Before you start: check your server&#39;s info&quot;">​</a></h2><blockquote><p>Run these three commands on your server and note the results; you will need them to pick the right bundle:</p></blockquote><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/os-release</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # OS: Rocky Linux 9 / Ubuntu 24.04 / Debian 12 ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # CPU architecture: x86_64 or aarch64 (aarch64 = ARM64)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Python version: 3.11 or newer is required</span></span></code></pre></div><ul><li><strong>OS</strong> is in the supported set: EL 9 family / Ubuntu 24.04 / Ubuntu 22.04 / Debian 12 (see the <a href="/en/guide/platforms">Platform Matrix</a>)</li><li><strong>Architecture</strong> is either <code>x86_64</code> or <code>aarch64</code></li><li><strong>Python</strong> version is &gt;= 3.11</li></ul><blockquote><p>💡 <strong>Root is not required.</strong> A regular user can install (into their home directory); installing as root makes Ansible available system-wide.</p></blockquote><ul><li>The machines Ansible will manage (managed nodes) need nothing special: just SSH and any Python. That is Ansible&#39;s own rule, unrelated to this project.</li></ul><h2 id="install-in-3-steps-beginner-path" tabindex="-1">Install in 3 steps (beginner path) <a class="header-anchor" href="#install-in-3-steps-beginner-path" aria-label="Permalink to &quot;Install in 3 steps (beginner path)&quot;">​</a></h2><h3 id="step-1-download-the-bundle-that-matches-your-server" tabindex="-1">Step 1: Download the bundle that matches your server <a class="header-anchor" href="#step-1-download-the-bundle-that-matches-your-server" aria-label="Permalink to &quot;Step 1: Download the bundle that matches your server&quot;">​</a></h3><ul><li>Use the table on the <a href="/en/guide/download">Download &amp; Verify</a> page to pick and download your bundle. From inside China, the Gitee mirror is usually faster.</li></ul><h3 id="step-2-copy-the-bundle-to-the-offline-server-and-extract-it" tabindex="-1">Step 2: Copy the bundle to the offline server and extract it <a class="header-anchor" href="#step-2-copy-the-bundle-to-the-offline-server-and-extract-it" aria-label="Permalink to &quot;Step 2: Copy the bundle to the offline server and extract it&quot;">​</a></h3><ul><li>Copy the <code>.tar.gz</code> file to the server (USB, bastion host, internal file server), then:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ansible-offline-install-2.0.0-el9-aarch64-py311.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ansible-offline-install-2.0.0-bundle</span></span></code></pre></div><h3 id="step-3-run-the-installer-and-check-the-result" tabindex="-1">Step 3: Run the installer and check the result <a class="header-anchor" href="#step-3-run-the-installer-and-check-the-result" aria-label="Permalink to &quot;Step 3: Run the installer and check the result&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><ul><li>The script prints its progress line by line (in Chinese by default; add <code>--lang en</code> for English) and runs a self-check at the end. Output containing <code>&quot;ping&quot;: &quot;pong&quot;</code> means success:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ansible-offline] Verifying installation</span></span>
<span class="line"><span>localhost | SUCCESS =&gt; {</span></span>
<span class="line"><span>    &quot;changed&quot;: false,</span></span>
<span class="line"><span>    &quot;ping&quot;: &quot;pong&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>[ansible-offline] Done. Ansible is ready, fully offline.</span></span></code></pre></div><blockquote><p>✅ Try <code>ansible --version</code> - if it prints a version, you are ready to write your first playbook.</p></blockquote><ul><li>Stuck? Check the <a href="/en/guide/faq">FAQ</a>. Want a different Ansible version or a different set of collections? See <a href="/en/guide/build">Build Your Own Bundle</a>.</li></ul><h2 id="glossary-when-a-term-is-unclear" tabindex="-1">Glossary (when a term is unclear) <a class="header-anchor" href="#glossary-when-a-term-is-unclear" aria-label="Permalink to &quot;Glossary (when a term is unclear)&quot;">​</a></h2><ul><li><strong>Offline bundle</strong>: one archive file containing everything needed for installation, so it works on machines without internet.</li><li><strong>wheel</strong>: Python&#39;s prebuilt package format - like a Windows installer; no compiling at install time, fast and reliable.</li><li><strong>venv (virtual environment)</strong>: a dedicated folder holding this Ansible installation, isolated from the system; deleting the folder removes it completely.</li><li><strong>collection</strong>: an Ansible plugin package that adds features, e.g. modules for firewalls or cloud providers. This project bundles <code>ansible.posix</code> and <code>community.general</code>, the two most commonly used ones.</li></ul>`,22)])])}const k=a(i,[["render",l]]);export{u as __pageData,k as default};
